import base64, random, struct
def blk_compressed(lit, nbseq_bytes, symtype, llbound, streams):
    content = lit + nbseq_bytes + bytes([symtype, llbound]) + streams
    return content
def literals_raw(lit):
    return bytes([0xB0 | ((len(lit)>>16)&0xF), (len(lit)>>8)&0xFF, len(lit)&0xFF]) + lit
def literals_rle(lit):
    # bt_rle? not used
    return literals_raw(lit)
def blockhdr(btype, csize):
    return bytes([(btype<<6)|((csize>>16)&0x1F),(csize>>8)&0xFF,csize&0xFF])
def frame(blocks):
    out = b'\x00\x00\x00\x00' + b'\x25\xb5\x2f\xfd' + b'\x00'
    for btype, content in blocks:
        out += blockhdr(btype, len(content)) + content
    out += b'\xC0\x00\x00'
    return out
def nb(n):
    return bytes([n]) if n<0x80 else bytes([0x80|(n>>8), n&0xFF])

cands=[]
random.seed(99)
# Family M: multi-block. block1 produces output (raw literal block), block2 has ML-escape sequences with big offset
for i in range(150):
    # block1: bt_raw literals (blockType=1 raw? no - use compressed with raw lits + 1 seq), simplest: a raw-literal compressed block
    b1lit = bytes([random.randint(1,255) for _ in range(random.choice([4,16,64,200]))])
    b1 = literals_raw(b1lit) + nb(0)  # nbSeq=0 -> literals only
    # block2: sequences with ML escape
    ns = random.choice([1,2,3,5,10,30,100])
    L = random.randint(7,24)
    streams = bytearray([random.randint(0,255) for _ in range(L-1)]+[0x01])
    for j in range(len(streams)-1):
        if random.random()<0.6: streams[j]=random.choice([0xff,0xc0,0x1f,0x04,0xfc])
    b2lit = bytes([0x41]*random.choice([1,2,4,8]))
    b2 = literals_raw(b2lit) + nb(ns) + bytes([0x00, random.choice([0,1,2,4,0x10,0xff])]) + bytes(streams)
    cands.append(frame([(0,b1),(0,b2)]))
# Family N: single block, ML escape, many seq, 0xff dumps region (dumps region = streams area)
for i in range(150):
    ns = random.choice([2,4,8,16,32,64,127,255])
    L = random.randint(7,30)
    streams = bytes([random.choice([0,0xff,0xc0,0x1f,0x04,0xfc,0xfe]) for _ in range(L-1)]+[random.choice([1,2,4,0x80])])
    lit = bytes([0x41]*random.choice([0,1,2,4]))
    cands.append(frame([(0, literals_raw(lit)+nb(ns)+bytes([0x00,random.choice([0,1,4,0x20,0xff])])+streams)]))
# Family O: LL escape with many literals provided (litLen valid) + many seq
for i in range(100):
    nlit = random.choice([64,100,200,300])
    lit = bytes([random.randint(1,255) for _ in range(nlit)])
    ns = random.choice([2,4,8,16])
    streams = bytes([random.choice([0,0xff,0xfc,0xf8,0x04]) for _ in range(random.randint(6,15))]+[0x01])
    cands.append(frame([(0, literals_raw(lit)+nb(ns)+bytes([0x00,0])+streams)]))
with open('/tmp/fuzzbatch2.txt','w') as f:
    for c in cands: f.write(base64.b64encode(c).decode()+"\n")
print(len(cands))
PYEOF
