import base64, sys
def bsr(x): return x.bit_length()-1
def build_stream(nbSeq, ll_sym=1, off_sym=0, ml_sym=0x7f):
    bits=[]
    for i in range(nbSeq):
        for j in range(5,-1,-1): bits.append((ll_sym>>j)&1)
        for j in range(4,-1,-1): bits.append((off_sym>>j)&1)
        for j in range(6,-1,-1): bits.append((ml_sym>>j)&1)
    allbits=[1]+bits
    pad=(8-(len(allbits)%8))%8; allbits=allbits+[0]*pad
    nbytes=len(allbits)//8; stream=bytearray(nbytes)
    for i,bit in enumerate(allbits):
        bi=(len(allbits)-1)-i; stream[bi//8]|=(bit<<(bi%8))
    return bytes(stream)
def frame(lit, nbseq, llbound, streams):
    out=b'\x00\x00\x00\x00'+b'\x25\xb5\x2f\xfd'+b'\x00'
    lh=bytes([0xB0|((len(lit)>>16)&0xF),(len(lit)>>8)&0xFF,len(lit)&0xFF])
    nb=bytes([nbseq]) if nbseq<0x80 else bytes([0x80|((nbseq>>8)&0x7f),nbseq&0xFF])
    content=lh+lit+nb+bytes([0x00,llbound])+streams
    cs=len(content); bh=bytes([(cs>>16)&0x1F,(cs>>8)&0xFF,cs&0xFF])
    return out+bh+content+b'\xC0\x00\x00'
NS=int(sys.argv[1]); nlit=int(sys.argv[2]) if len(sys.argv)>2 else 1
st=build_stream(NS)
b=frame(bytes([0x41]*nlit), NS, 0x00, st)
sys.stdout.write(base64.b64encode(b).decode())
print("\nrawlen=%d stream=%d bytes"%(len(b),len(st)), file=sys.stderr)
