    allbits=[1]+bits; pad=(8-(len(allbits)%8))%8; allbits+=[0]*pad
    nbytes=len(allbits)//8; s=bytearray(nbytes)
    for i,bit in enumerate(allbits):
        bi=(len(allbits)-1)-i; s[bi//8]|=(bit<<(bi%8))
    return bytes(s)
def bh(bt,cs): return bytes([(bt<<6)|((cs>>16)&0x1F),(cs>>8)&0xFF,cs&0xFF])
def litraw(l): return bytes([0xB0|((len(l)>>16)&0xF),(len(l)>>8)&0xFF,len(l)&0xFF])+l
def nb(n): return bytes([n]) if n<0x80 else bytes([0x80|((n>>8)&0x7f),n&0xFF])
